package com.dlxyuki.wms.containertracking;
import com.dlxyuki.wms.user.UserAccount;import jakarta.validation.constraints.*;import java.time.LocalDate;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/v1/container-tracking") public class ContainerTrackingController{
 private final ContainerTrackingService service;public ContainerTrackingController(ContainerTrackingService s){service=s;}
 @GetMapping Object list(@RequestParam(defaultValue="1")@Min(1)int page,@RequestParam(name="per_page",defaultValue="20")@Min(1)@Max(100)int perPage,@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(name="warehouse_id",required=false)Long warehouseId,@RequestParam(name="outbound_window",required=false)String outboundWindow,@RequestParam(name="outbound_from",required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate outboundFrom,@RequestParam(name="outbound_to",required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate outboundTo,@RequestParam(name="dispatch_priority",required=false)String dispatchPriority,@RequestParam(name="sort_by",defaultValue="pod_eta")String sortBy,@RequestParam(name="sort_order",defaultValue="desc")String sortOrder,@AuthenticationPrincipal UserAccount user){return service.list(new ContainerTrackingQuery(page,perPage,q,status,warehouseId,outboundWindow,outboundFrom,outboundTo,dispatchPriority,sortBy,sortOrder),user);}
 @GetMapping("/{tracking_id}")Object detail(@PathVariable(name="tracking_id")long id,@AuthenticationPrincipal UserAccount user){return service.detail(id,user);}
}
